"""Simplified Chinese documentation aligned with app terminology."""
from content_en import section,doc
PAGES={}
PAGES['privacy-policy']=doc('隐私政策','Pattern 如何处理文件、权限、备份和共享。','内容首先保存在你的设备上。你可以为每个保险库单独选择是否启用云备份和共享。',[
section('scope','本政策的范围','''<p>本政策说明位于{{country}}的 {{publisher}}（以下简称“我们”）在 iPhone、iPad 版 Pattern 及支持服务中如何处理信息。无需注册 Pattern 账户。可选的 iCloud 功能需要已登录 iCloud 的 Apple 账户。如有隐私问题，请联系 {{contact}}。</p>'''),
section('at-a-glance','要点','''<ul><li>导入、拍摄或创建的文件存放在 App 的本地空间。</li><li>App 未集成广告网络、第三方分析 SDK 或跨 App 跟踪功能。</li><li>我们不出售个人信息，也不为定向广告共享个人信息。</li><li>可选的备份和共享副本会先在设备上加密，再上传到 iCloud。</li><li>解锁图案和恢复短语不会发送到开发者的账户服务器；Pattern 没有这样的服务器。</li></ul>'''),
section('local-data','设备上的信息','''<p>Pattern 保存照片、视频、备忘录、文档及缩略图和预览；保险库、文件夹、文件名称及类型、日期、大小、归属关系；图案和恢复短语的验证值、安全设置及失败尝试记录；备份和共享所需的秘密信息、iCloud 记录标识、接收者标签和打开次数；以及偏好、初始设置进度和优惠期限。</p><p>原文件可能包含日期、拍摄位置等元数据。Pattern 不保证在导入、导出、备份或共享时删除这些信息，也不申请设备定位权限。</p><p>不会保留原始解锁图案。常规恢复设置保存验证值，而非可读的恢复短语。胁迫模式生成的新短语会暂时保留在受保护的凭据记录中，直到你确认已保存。</p>'''),
section('protection','保护方式','''<p>本地文件采用 iOS 完整文件保护。图案负责控制 App 内的访问；<strong>本地媒体并非使用从图案派生的密钥加密</strong>。凭据记录另有与本次安装绑定的 AES-256-GCM 加密层。</p><p>iCloud 备份、便携备份文件和共享归档采用 AES-256-GCM，使用与解锁图案不同的秘密信息。Pattern 会遮盖 App 切换器中的内容，并在进入后台后要求重新解锁。</p><p>任何 App 都无法保证已遭入侵设备的安全，也不能阻止所有截图或外部相机拍摄。请按<a href="manual.html#recovery">恢复指南</a>保留可用的备份。</p>'''),
section('icloud','可选的 iCloud 备份','''<p>备份默认关闭。启用后，App 会将加密的归档和保险库元数据上传至你的私有 CloudKit 数据库。恢复短语保护恢复归档所需的秘密信息；不会以可读字段上传原短语或该秘密信息。</p><p>Apple 运营存储服务，可能处理账户或记录标识、时间、传输大小和连接信息。内容加密不会隐藏所有服务元数据。详见 <a href="https://www.apple.com/legal/privacy/">Apple 隐私政策</a>和 <a href="https://www.apple.com/legal/internet-services/icloud/en/terms.html">iCloud 条款</a>。</p><p>备份在保险库打开时执行，只保留最近完成的一份，不提供版本历史。它与普通设备备份和 iCloud 照片相互独立。</p>'''),
section('sharing','共享保险库','''<p>共享会创建一份加密、只读的云端副本。公共 CloudKit 数据库中的加密邀请记录用于通过共享短语查找邀请，其中不含可读的保险库媒体或原始短语，但仍可能关联账户和记录元数据。</p><p>最先领取邀请的 Apple 账户成为接收者。接收者能看到内容及其元数据，并在你允许时导出。即使不允许导出，也可能拍摄屏幕，因此仅向预期接收者发送短语。</p><p>接收的内容会缓存在本地，但打开前和查看过程中都需要在线检查权限。有效期、打开次数和截屏后锁定是 App 规则，不保证无法复制。撤销共享不能删除已另存的副本。</p>'''),
section('permissions','权限与选择','''<ul><li><strong>照片：</strong>系统选择器只提供你选中的项目。成功导入后，如选择删除原件，App 会请求更广的照片权限并由系统确认。导出目标可能还需要自身权限。</li><li><strong>相机与麦克风：</strong>打开相机时使用相机，录制带声音的视频时使用麦克风。拍摄内容在点按“使用”前是私有草稿，不会自动保存到“照片”。</li><li><strong>Face ID / Touch ID：</strong>Apple 返回认证结果，Pattern 不接收人脸扫描、指纹或生物识别模板。</li><li><strong>文件与共享表单：</strong>访问所选文档，或将所选文件、短语传给指定目标。目标之后按自身规则处理。</li><li><strong>剪贴板：</strong>使用明确的粘贴操作，不持续读取。复制的短语仅限本机，并会到期。</li></ul><p>你可以在系统设置中更改权限。拒绝权限会限制相关功能。</p>'''),
section('purchases','购买与诊断','''<p>付款由 Apple 处理。Pattern 使用 StoreKit 交易及已验证的购买权益，包括产品、交易标识和购买状态，来解锁功能。我们不会通过 App 获得你的银行卡信息。</p><p>当前 App 没有自建分析或崩溃上传 SDK。Apple 可能按你的系统设置和其政策向开发者提供统计和诊断。请查看“分析与改进”及 <a href="https://www.apple.com/legal/privacy/data/en/app-analytics/">Apple App 分析隐私说明</a>。</p>'''),
section('retention','保留与删除','''<ul><li>本地内容会保留到你删除项目、保险库或 App。删除文件夹会保留其中项目；删除项目没有 App 内废纸篓。</li><li>本地保险库文件及安装密钥不纳入普通设备备份。需要可恢复副本时，请使用 Pattern 的加密备份。</li><li>“关闭并删除云备份”停止上传并请求移除已配置的云端副本，本地文件保留。</li><li>删除自有保险库会删除本地内容和凭据，并排队删除该库的云备份和自有共享。删除接收的保险库只移除本地副本。</li><li>云端删除可能等待网络和正确的 iCloud 账户。保持 App 安装并重新打开以完成任务；删除 App 可能丢失待办请求。</li><li>删除 App 本身不会删除已完成的 iCloud 备份、照片原件、购买或外部导出文件。“卸载 App”保留文稿和数据，与彻底删除不同。</li><li>外部及接收者副本需另行管理。删除照片原件可能影响 iCloud 照片及同步设备，且可能保留在“最近删除”中。</li></ul><p>胁迫模式会移除其他本地保险库的凭据，但文件仍留在磁盘，并非安全擦除。启用前请阅读<a href="manual.html#duress">全部影响</a>。Apple 和目标服务对运营记录及服务备份等适用自身保留规则。</p>'''),
section('support-rights','支持与信息权利','''<p>我们使用你主动提供的邮箱、消息和附件来回复、排查问题及处理隐私安全事项，只在这些目的或法律义务合理需要的期间保留。可能使用邮件、支持服务商，或依法披露相关信息。</p><p>请勿发送图案、恢复短语、共享短语或私有文件。我们没有可以替你重设图案或解密遗失备份的服务器副本。</p><p>根据所在地，你可能享有访问、更正、删除、获取副本、限制或反对处理、撤回同意或向主管机关投诉等权利。针对我们持有的信息，请联系 {{contact}}；可能需要适度验证身份。本地保险库在你的设备上管理，涉及 Apple 自身处理的问题也请联系 Apple。</p>'''),
section('children-changes','未成年人及政策更新','''<p>Pattern 不要求出生日期，也不创建单独的儿童档案。Apple 账户要求、App Store 年龄分级及当地法律所需的监护人许可仍适用。</p><p>顶部显示修订日期。重大变更将遵守法律要求的通知及同意程序。本政策针对 App 与支持服务；其他网站服务或跟踪工具需要相应披露。</p>''')])
PAGES['terms-of-use']=doc('使用条款','Pattern 及其可选云功能的使用条件。','了解许可、你的责任，以及恢复和共享的限制。',[
section('agreement','关于本条款','''<p>Pattern 由位于{{country}}的 {{publisher}} 提供。你应具备接受适用条件的资格，或获得法律要求的监护人许可。除非 App Store 下载时另附许可，App 适用 <a href="https://www.apple.com/legal/internet-services/itunes/dev/stdeula/">Apple 标准最终用户许可协议</a>。本条款补充该许可，不取代 Apple 条款或强制性消费者权利。另请参阅<a href="privacy-policy.html">隐私政策</a>。</p>'''),
section('service','功能与限额','''<p>Pattern 将照片、视频、备忘录、文档存放在通过图案打开的本地保险库中，可选择生物识别、加密备份和只读共享。需 iOS/iPadOS 26.2 或以上版本，以及相应硬件、权限、空间和 Apple 服务支持。</p><p>免费版可拥有三个自有保险库，每个总计五个项目，包括所有类型和文件夹内的项目。接收的共享保险库不占这些限额。Pro 移除 App 限额并允许创建共享；设备和 iCloud 容量仍有限制。</p>'''),
section('purchases','购买、优惠及退款','''<p>Pro 是非消耗型一次性购买，不是订阅。常规购买和优惠解锁同样功能，价格、货币、税费、供应和资格以 Apple 购买界面为准，优惠可能到期。购买须经 Apple 确认。</p><p>“恢复购买”恢复原 Apple 账户的功能权益，不恢复文件。待处理、取消或未验证交易不会解锁。退款或撤销可能移除付费权益；当前 App 仍允许查看、按权限导出或删除已有本地内容，仅对新添加应用免费限额。</p><p><a href="https://support.apple.com/en-us/118223">退款由 Apple</a> 按规则及法律处理，不影响你的法定救济。一次性购买不保证第三方服务永久提供或适配所有未来设备。</p>'''),
section('your-content','内容与允许的用途','''<p>你保留内容权利，只授权完成所选存储、备份、导出和共享所需的处理，不向我们转让文件所有权。</p><p>你应取得拍摄、保存和共享所需的权利及同意。不得侵犯隐私或知识产权、剥削或伤害他人、传播违法材料、未经授权访问或干扰服务。静音拍摄不会免除录制及同意要求。App 不提供公开内容流或公开保险库目录。</p>'''),
section('security-recovery','保护与恢复责任','''<p>请保护设备、Apple 账户、图案和短语，并将恢复信息保存在 Pattern 之外。本地媒体使用 iOS 文件保护及 App 访问锁，而非图案派生的媒体加密。备份归档另行加密。无法保证绝对保密或受侵害设备的安全。</p><p>短语本身不能重建已删除文件。必须有完成的备份及其有效短语。保险库不纳入普通设备备份，请在删除 App、重置或更换设备前确认备份可用。我们无法恢复丢失的秘密信息。</p>'''),
section('cloud-sharing','云服务与共享','''<p>功能依赖 Apple、网络、正确账户及可用容量，并适用 <a href="https://www.apple.com/legal/privacy/">Apple 隐私政策</a>及 <a href="https://www.apple.com/legal/internet-services/icloud/en/terms.html">iCloud 条款</a>。备份在前台执行并保留最新完成副本，不是双向同步。</p><p>每个邀请由一个 Apple 账户领取，接收副本只读且需在线验证。到期、每次安装的打开限额、导出规则及捕获后锁定并不能保证内容未被复制。撤销须传至 iCloud，不能抹掉已有导出、截图或外部照片。删除 App 前请完成需要的云端清理。</p>'''),
section('duress','胁迫模式与不可逆操作','''<p><strong>胁迫模式有重大后果。</strong>启用后，当前图案成为触发图案。以后用它解锁会保留指定伪装库，未指定时保留触发库，并移除所有其他本地保险库凭据。它还会更新保留库的恢复短语，停止本次安装的备份和共享，并排队撤销自有共享。</p><p>其他文件仍在磁盘，但旧图案和短语不能再打开。关闭功能不能撤回这些结果。可用的独立备份须另行恢复。这不是安全擦除、紧急服务或隐藏数据、人身安全保证。生物识别失败而进入伪装库并不会触发胁迫模式。删除时也请阅读确认内容。</p>'''),
section('availability-liability','可用性与法律权利','''<p>不能保证服务不中断、软件无错误或所有恢复成功。更新可能改变功能和兼容性；法律要求时会通知影响权利的重大变更。</p><p>适用许可中的保证、责任、终止和争议条款继续有效。本条款不排除依法不能排除的责任或消费者保护，也不新增强制仲裁或不同的专属法院。你可随时停止使用；先保存所需文件，另行删除云端副本。合理需要继续有效的条款仍然适用。</p>'''),
section('contact-changes','联系与修订','''<p>联系：{{contact}}。请勿发送图案或秘密短语，提交截图前请遮盖私有内容。版本日期在顶部。重大修订遵循适用的通知和同意要求。各译本不限制当地强制性权利；如有表述不一致，请联系澄清。</p>''')])
PAGES['manual']=doc('使用手册','Pattern 的初始设置与日常操作指南。','设置图案、保存恢复短语，然后添加需要私密保存的内容。',[
section('start','1. 创建第一个保险库','''<ol><li>完成或跳过介绍，选择<strong>创建新保险库</strong>。已有备份或邀请时，请选择恢复或加入共享。</li><li>选择 3 × 3、4 × 4 或 5 × 5 网格，并为保险库命名。</li><li>绘制至少包含四个不同点的图案，再重复一次。路径经过的点会自动加入，同一笔中不能重复使用一个点。</li><li>建议使用自动生成的 20 词恢复短语，也可使用至少八个词、40 个字符的自定义短语。通过<strong>保存到备忘录</strong>或<strong>复制短语</strong>将其存放在 App 外。</li><li>重复输入完整短语，确认已在外部保存。购买提示可以关闭，继续使用免费版。</li></ol><div class="callout">短语应保存在即使失去本设备也能访问的地方。切换 App 会在内存中保留未完成设置；进程结束可能丢失这些步骤。</div><p>需 iOS/iPadOS 26.2 或以上版本。</p>'''),
section('vaults','2. 打开和切换保险库','''<p>每个已登记图案打开对应保险库。通过资料库顶部的<strong>新建保险库</strong>设置新名称及两次相同的新图案。图案必须唯一；未知图案不会自动创建保险库。</p><p>切换时先锁定，再绘制另一个图案。进入后台后会锁定，App 切换器会遮盖内容。多次错误会产生持续保留的等待时间。免费版有三个自有库、每库五个项目；接收的共享不计入。</p>'''),
section('add','3. 添加照片、视频、备忘录和文档','''<p>打开目标库或文件夹后选择添加：从照片选择器导入媒体、使用私密相机、创建备忘录，或从“文件”导入文档。不支持预览的文档也可保存和导出。导入只复制，不删除来源。</p><p>删除照片原件是成功导入后的独立操作，需要系统确认，并可能影响 iCloud 照片同步的其他设备。Pattern 不会清空“最近删除”。Live Photo 当前仅导入静态图像，不自动删除原件；若需要动态内容，请保留原件。</p>'''),
section('camera','4. 使用私密相机','''<ol><li>在添加菜单中打开相机并授权；录制带声音的视频时需麦克风权限。</li><li>选择照片或视频及可用的摄像头，然后拍摄。</li><li><strong>使用</strong>会保存到当前库或文件夹。<strong>重拍</strong>、取消或进入后台会丢弃未确认草稿。</li></ol><p>不会自动保存副本到“照片”。划线扬声器选项使用兼容摄像头的 ARKit 视频帧生成静音照片，细节可能低于普通高分辨率照片。该选项不会关闭视频录音。系统拍摄或确认界面可能仍为深色。</p>'''),
section('organize','5. 搜索、筛选与整理','''<ul><li><strong>搜索：</strong>在当前资料库或文件夹中查找项目名、文件名，并结合筛选条件；不搜索文档正文。换文件夹或添加内容会清空搜索。</li><li><strong>排序：</strong>箭头图标可按导入日期、名称、文件日期、从大到小或从小到大排序。文件日期优先使用可用原始元数据，否则使用替代日期。</li><li><strong>筛选：</strong>全部、照片、视频、备忘录或文档。</li><li><strong>选择：</strong>圆圈勾选图标用于单选、全选、移动、导出、删除，再次点按可结束选择。</li><li><strong>文件夹：</strong>可创建、重命名、改颜色或删除，并移动项目。删除文件夹保留其中的文件。</li></ul><p>较宽的 iPad 界面提供侧边栏。照片支持缩放、翻页；视频使用原生控件，离开视频或进入后台时暂停。</p>'''),
section('export-delete','6. 导出与删除','''<p>选中项目后通过共享表单导出到“文件”或其他目标。导出的是普通副本，可能保留元数据，不是加密的 Pattern 备份。需要加密归档时使用<a href="#file-backup">文件备份</a>。</p><p>接收的保险库只有在所有者允许时才能导出。确认删除项目会移除 App 内副本，没有内部废纸篓；照片原件和以前导出的副本不受影响。</p>'''),
section('recovery','7. 图案、恢复短语与网格','''<p>在<strong>保险库设置</strong>中确认当前图案，然后输入两次新图案即可更改。忘记图案时，在锁定屏幕选择<strong>找回保险库</strong>，用该库恢复短语设置新图案。多次错误会触发等待。</p><p>更换短语时先在 App 外保存新的短语，重复输入并确认当前图案。旧短语会立即失去本地恢复作用。已有云备份在下一次备份完成前仍使用旧短语；已导出文件始终需要生成当时的短语。</p><p>网格更改影响所有保险库。逐一确认旧图案、两次输入唯一新图案；如任意库启用了生物识别，还需认证。检查后保存。取消会保持原状；成功后锁定已打开的窗口。</p><div class="callout">恢复访问不等于备份。找回删除的文件还必须有可用归档及对应短语。</div>'''),
section('icloud-backup','8. 备份到 iCloud','''<ol><li>打开自有库，在设置中选择<strong>加密 iCloud 备份</strong>。</li><li>输入恢复短语并启用。</li><li>保持库打开、网络连接及足够空间，等待“上次完成备份”显示日期。</li><li>更换设备前执行新的备份。若中断，重新打开库再试。</li></ol><p>各库分别启用，仅保存一份最近完成版本，没有历史记录或双向同步。<strong>关闭并删除云备份</strong>会请求删除云端副本，保留本地文件。待处理操作需要原 iCloud 账户及连接。</p>'''),
section('restore','9. 从 iCloud 恢复','''<ol><li>登录拥有该备份的 Apple 账户。</li><li>在初始设置、锁定屏幕或备份设置中选择<strong>从 iCloud 恢复</strong>。</li><li>选择带日期的备份，并输入最后完成上传所使用的短语。</li><li>设置唯一的本地名称和新图案。</li><li>恢复后设置新恢复短语，按需要重新开启今后的备份。</li></ol><p>会新建保险库，不覆盖其他库。名称经过加密，因此初始列表按日期识别。免费限额在安装前检查，过大的归档不会被悄悄截断。单有图案或短语不能重建已删除媒体。</p>'''),
section('file-backup','10. 使用加密备份文件','''<p>在<strong>文件备份 → 导出备份文件</strong>中输入恢复短语，通过“文件”保存 <code>.patternbackup</code>。文件和短语请分开保管。若选择 iCloud Drive 等云服务，要等待其上传完成。</p><p>文件是一个时间点的快照，后续变化需要重新导出。使用<strong>导入备份文件</strong>选择归档和创建时的短语，再建立新保险库。更改当前恢复短语不会重写已有归档。</p>'''),
section('share','11. 共享或接收保险库','''<p>Pro 用户在自有库设置中打开<strong>共享</strong>。可设置接收者标签、有效期、最大打开次数、导出许可或捕获后锁定。选择<strong>创建共享短语</strong>，等待上传完成，再私下发送。离开显示页面后不会再次显示该短语。请勿发送恢复短语。</p><p>接收者选择<strong>加入共享保险库</strong>，在登录 iCloud 的状态下输入短语，设置本地名称和图案。最先领取的 Apple 账户成为接收者，可用同一短语再次导入。接收免费，不占自有库限额。</p><p>副本只读，打开前及查看过程中需在线验证。所有者打开库时发送更新，接收者重新打开时获取可用版本。</p><p>在共享设置中撤销访问，并保留 App 直到请求传至 iCloud。打开次数按安装记录，删除或重装可能重置。捕获检测后的锁定不能阻止第一张截图或外部相机。已经导出的内容不在 Pattern 控制范围内。</p>'''),
section('biometrics','12. 生物识别与伪装保险库','''<p>在<strong>Face ID 与伪装保险库</strong>或 Touch ID 对应设置中选择另一个已有库，启用保护，并完成图案及生物识别确认。图案选择受保护库，认证成功后打开；设备密码不能替代。</p><p>失败、拒绝、取消或不可用时，会打开指定伪装库；系统中断会保持锁定。伪装会话可操作媒体，但不能访问库设置或创建库。使用伪装库本身的图案可获得完整权限。若伪装库已被删除，认证失败后仍锁定。<strong>生物识别失败不会启动胁迫模式。</strong></p>'''),
section('duress','13. 了解胁迫模式','''<div class="callout warning">没有独立、可用的备份时，请勿对不可替代的内容启用或测试此功能。</div><p><strong>使用胁迫保险库</strong>在说明、同意和图案确认后，将当前图案设为触发图案，设置本身不会立即触发。之后用该图案解锁会：</p><ul><li>保留指定伪装库，未指定时保留触发库。如果保留的是另一个伪装库，触发库本身也失去访问；</li><li>移除所有其他本地库的凭据，旧图案和恢复短语无法再打开，尽管文件仍在磁盘；</li><li>为保留库生成新短语。请用<strong>保存新恢复短语</strong>将其存到 App 外；</li><li>停止此次安装的云端和手动备份、共享，并排队撤销自有共享。以前的个人云备份及单独导出的备份文件不会擦除。</li></ul><p>关闭模式不恢复已移除访问，也不重新启用备份。恢复独立备份是另外的操作。在设置内确认图案不会触发。此功能不是安全擦除，也不保证数据不会被发现。</p>'''),
section('icons-language','14. 更改图标或语言','''<p>在<strong>App 设置 → App 图标</strong>中选择样式，Classic 可恢复主图标。图标适用于设备上的所有库，不改变访问方式或已安装 App 的名称。</p><p>主屏幕名称指南帮助创建单独命名的 Apple 快捷指令，以所选图片执行“打开 App → Pattern”。它不会重命名、隐藏或删除原 App。</p><p>支持英语、日语、韩语、法语、德语、意大利语和简体中文。在系统允许时，可在设备设置中更改 App 语言。你自己的名称、文件名和短语用词不会翻译。</p>'''),
section('purchases-removal','15. 购买、删除与帮助','''<p>在库设置的 <strong>Pattern Pro</strong> 中一次性购买，或用原 Apple 账户<strong>恢复购买</strong>。优惠与常规购买功能相同，恢复购买不会恢复媒体。</p><p>删除库需要名称及当前图案。它移除本地内容和凭据；若为自有库，也请求删除已配置云备份和共享。其他库、照片原件和导出保留。删除接收库只移除本地副本。</p><p>彻底删除 App 会删除本地库和安装密钥，保留数据的“卸载 App”则不同。先检查备份并完成需要的云端删除。可查阅<a href="faq.html">常见问题</a>或联系 {{contact}}，提供版本及错误信息，切勿发送秘密短语。</p>''')])
FAQ=[
('basics','基本使用',[
('account','需要账户吗？','无需 Pattern 账户。自有本地保险库可离线使用；iCloud 备份和共享需要已登录的 Apple 账户及网络。'),
('free','免费版与 Pro 有什么区别？','免费可建三个自有库，每库总共五个项目，涵盖所有类型和文件夹。接收共享免费且不占限额。Pro 移除 App 限额并允许创建共享，但仍受存储容量限制。'),
('patterns','每个图案都会打开不同的库吗？','已创建的库各有图案。请用“新建保险库”添加；陌生图案不会自动生成新库。'),
('grid','可以更改网格大小吗？','可以在 3 × 3、4 × 4、5 × 5 间切换，影响所有库，需确认旧图案及唯一的新图案。<a href="manual.html#recovery">查看步骤。</a>'),
('subscription','Pro 是订阅吗？','不是。常规和优惠均为非消耗型一次性购买，功能相同，以 Apple 界面所示价格为准，没有 Pattern 定期收费。')]),
('files','文件与相机',[
('originals','导入会删除原件吗？','不会。删除照片原件是成功导入后的单独确认操作，可能同步到 iCloud 照片。Pattern 不清空“最近删除”，文档来源也保留。'),
('live-photos','如何导入 Live Photo？','目前仅保存静态图像，不自动删除原件。如需动态部分，请保留原件。'),
('camera-photos','私密相机会保存到“照片”吗？','不会自动保存。“使用”保存至当前库或文件夹；重拍、取消或进入后台会丢弃未确认草稿。以后可以自行导出。'),
('silent','为什么静音照片不可用或不够清晰？','它使用兼容摄像头的 ARKit 视频帧，不是正常高分辨率拍照，细节可能更少。该设置不关闭视频录音。'),
('search','为什么搜索找不到文件？','只查当前库或文件夹中的名称，并受筛选条件限制，不查文档正文。请检查文件夹及筛选。换文件夹或新增内容会清空搜索。'),
('folder-delete','删除文件夹会删除文件吗？','不会，项目仍在库中。删除项目本身是另一项需确认的操作。'),
('metadata','会去掉日期和位置信息吗？','不保证。原始元数据可能在导入、导出和共享副本中保留。Pattern 不是元数据清理工具。')]),
('security','保护与恢复',[
('encryption','图案会加密所有文件吗？','不会。图案是 App 访问锁。本地文件使用 iOS 完整文件保护，凭据有安装绑定加密。云端及便携归档以独立秘密信息进行 AES-256-GCM 加密。'),
('forgot','忘记图案怎么办？','通过“找回保险库”用恢复短语设置新图案。两者都没有时，支持方不能绕过锁。若有可用备份及原短语，可单独恢复。'),
('deleted-app','删除 App 后仅凭短语能恢复吗？','还需已完成的云备份或 .patternbackup 文件。短语不含媒体。重新安装或恢复购买不会恢复不在普通设备备份内的保险库。'),
('changed-phrase','旧备份要用哪一个短语？','导出文件始终使用创建时的短语。更改后，云端旧副本在下一次备份完成前仍需旧短语；本地恢复立即使用新短语。'),
('biometric-dummy','为什么生物识别打开了别的库？','失败、取消或不可用时会显示设置的伪装库，不会因此启动胁迫模式或修改备份。系统中断保持锁定。用伪装库自身图案可访问完整设置。'),
('duress-effect','胁迫模式具体做什么？','触发图案保留指定伪装库或触发库，删除其他本地凭据，更新保留库短语，停止备份与共享并排队撤销共享。其他文件留在磁盘，关闭功能不会撤回结果。<a href="manual.html#duress">先阅读全部后果。</a>'),
('capture','能完全阻止截图吗？','不能。共享库的捕获锁定可在检测后限制访问，但无法保证阻止第一张截图或另一台相机拍摄。')]),
('cloud','备份与共享',[
('sync','iCloud 会自动同步所有设备吗？','不会。打开库时保存最新完成备份，恢复会建立独立本地库。没有双向同步或版本历史。'),
('backup-failure','备份一直没完成。','检查网络、设备及 iCloud 容量、原 Apple 账户。打开库重试，确认完成日期并记录错误。未验证备份前，不要通过删除 App 来排查。'),
('no-backups','为什么找不到可恢复备份？','须使用所有者账户，且至少一次上传已完成。设备备份、iCloud 照片、iCloud Drive 文件都不同。.patternbackup 文件请用“导入备份文件”。'),
('shared-offline','收到的库能离线打开吗？','打开前和查看过程中都需要在线检查。自有本地库可以离线。接收库的导出还需所有者许可。'),
('sharing-phrase','共享短语就是恢复短语吗？','不是。只发送生成的共享短语。首先领取的 Apple 账户成为接收者，可用原短语重新导入。图案与恢复短语须保密。'),
('revoke','撤销会删除对方所有副本吗？','不会。iCloud 收到撤销并重新检查权限后，阻止共享渠道访问。导出、截图、外部照片仍存在。请保持 App 安装以完成待办撤销。'),
('open-limit','打开次数跨设备累计吗？','不累计，按本地安装记录，重启后保留；删除接收库或重装可能重置。这不是防故意绕过的机制。'),
('remove-cloud','怎样删除云备份？','在库设置中选择“关闭并删除云备份”，联网后请求移除，保留本地文件。仅删除 App 不移除完成的备份。<a href="privacy-policy.html#retention">查看保留说明。</a>')]),
('appearance-help','外观、购买与支持',[
('icon-name','更改图标也会改名吗？','已安装 App 仍叫 Pattern。快捷指令指南创建另一个命名的启动入口，不会更改或隐藏原 App。'),
('restore-purchase','怎样恢复 Pro？','用购买时的 Apple 账户进入 Pattern Pro → 恢复购买。Apple 可能要求登录。它恢复功能权益；文件须从备份恢复。'),
('refund','怎样申请退款？','使用 <a href="https://support.apple.com/en-us/118223">Apple 退款流程</a>，资格取决于购买、国家或地区及法律。失去 Pro 后，当前 App 保留已有本地内容的访问并限制新添加。'),
('help','联系支持时提供什么？','向 {{contact}} 提供 App/iOS 版本、复现步骤、错误信息和已遮盖私有内容的截图。不要发送库内文件、图案、恢复或共享短语、银行卡信息。')])]
PAGES['faq']=dict(title='常见问题',description='关于隐私、恢复、iCloud 及日常使用的解答。',lead='快速找到答案，并查看相应操作步骤。',faq=FAQ)
